import pandas as pd
import numpy as np
import re

df = pd.read_csv('/app/dataset/data.csv')

def parse_notes(notes_str):
    if pd.isna(notes_str):
        return {
            'items': None,
            'adj_pct': 0.0,
            'fee': 0.0,
            'waive': False
        }

    parts = str(notes_str).split(";")
    items = None
    adj_pct = 0.0
    fee = 0.0
    waive = False

    for part in parts:
        part = part.strip()
        if not part:
            continue
        if "=" in part:
            key, val = part.split("=", 1)
            key = key.strip().lower()
            val = val.strip()

            if key == "items":
                try:
                    items = int(val)
                except ValueError:
                    items = None
            elif key == "adj":
                try:
                    val_clean = val.replace("%", "").strip()
                    adj_pct = float(val_clean) / 100.0
                except ValueError:
                    adj_pct = 0.0
            elif key == "fee":
                try:
                    fee = float(val)
                except ValueError:
                    fee = 0.0
            elif key == "waive":
                if val.lower() == "true":
                    waive = True

    return {
        'items': items,
        'adj_pct': adj_pct,
        'fee': fee,
        'waive': waive
    }

# Apply to df
parsed_notes_df = df['notes'].apply(parse_notes).apply(pd.Series)
df = pd.concat([df, parsed_notes_df], axis=1)

print("Parsed notes summary:")
print(df[['notes', 'items', 'adj_pct', 'fee', 'waive']].head(20))

print("\nWaive is True examples:")
print(df[df['waive'] == True][['notes', 'items', 'adj_pct', 'fee', 'waive']].head(10))

